={{ (() => { const d = $('Decide reply').item.json; const e = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const failed = $('Record delivery').isExecuted && $('Record delivery').item.json.delivered === false;
  return [
    d.hot ? '🔥 <b>Hot lead</b>' : '🙋 <b>Lead needs a human</b>',
    '',
    '<b>Name:</b> ' + e(d.contact_name || 'unknown') + ' (' + e(d.source) + ')',
    '<b>Score:</b> ' + (d.fit_score ?? 'n/a') + ' · ' + e(d.intent ?? 'unqualified') + ' · urgency ' + e(d.urgency ?? 'unknown'),
    '<b>Reason:</b> ' + e(d.reason),
    '<b>Message:</b> ' + e(String(d.message).slice(0, 300)),
    '<b>Reply sent:</b> ' + (d.reply ? e(d.reply) : '(none)') + (failed ? ' ⚠️ WhatsApp did not accept it' : ''),
    '<b>Lead #' + d.lead_id + '</b>',
  ].join('\n'); })() }}

