// Returned to the calling workflow (the form uses it as the HTTP response).
const d = $('Decide reply').first().json;
const delivered = $('Record delivery').isExecuted ? $('Record delivery').first().json.delivered : (d.reply && d.source === 'form' ? true : null);
return [{ json: {
  lead_id: d.lead_id, conversation_id: d.conversation_id, status: delivered === false ? 'needs_human' : d.status,
  reply: d.source === 'form' ? d.reply : null, delivered, hot: d.hot,
  schema_valid: d.schema_valid, attempts: d.attempts,
} }];

