={{ (() => { const h = $('Hand off to owner').item.json; const l = $('Normalise lead').first().json;
  const e = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const ack = $('Record acknowledgement').isExecuted ? ($('Record acknowledgement').item.json.delivered ? 'sent' : '⚠️ WhatsApp did not accept it') : 'already sent earlier';
  return [
    '💬 <b>Lead replied, over to you</b>',
    '',
    '<b>Name:</b> ' + e(h.contact_name || 'unknown') + ' (' + e(l.source) + ')',
    '<b>Score:</b> ' + (h.fit_score ?? 'n/a') + ' · ' + e(h.intent ?? 'unqualified'),
    '<b>Their message:</b> ' + e(l.message.slice(0, 300)),
    '<b>Bot said earlier:</b> ' + e(h.first_reply || '(nothing)'),
    '<b>Acknowledgement:</b> ' + (l.source === 'whatsapp' ? ack : 'n/a (form lead)'),
    '<b>Lead #' + h.lead_id + '</b>',
  ].join('\n'); })() }}
